import{_ as o,l as s,o as e,c as n,v as t,p as l,x as r,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"并发跳表","description":"","frontmatter":{"title":"并发跳表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/concurrent-skip-list.md","filePath":"cs/concurrent-skip-list.md","lastUpdated":1789023840000}'),h={name:"cs/concurrent-skip-list.md"};function A(E,a,u,_,S,m){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="并发跳表" tabindex="-1">并发跳表 <a class="header-anchor" href="#并发跳表" aria-label="Permalink to &quot;并发跳表&quot;">​</a></h1><div class="epigraph"><p>跳表没有必须旋转的根；各层前向指针可以用 CAS 接线，查找甚至常常无锁只读。</p><footer>—— 据 Pugh, Concurrent Maintenance of Skip Lists, 1990；Herlihy and Shavit, The Art of Multiprocessor Programming 整理</footer></div><p><a href="/cs/order-statistic-tree">上一课</a>的树要旋转，旋转碰祖先，细粒度锁难。<a href="/cs/skip-list">跳表</a> 的形状是局部接线。<a href="/cs/lockfree-aba">无锁与 ABA</a> 已警告 CAS 位型。本课不重讲随机层高期望。缺口是并发跳表：查找无锁遍历，插入删除对前驱指针 CAS（或分层锁）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>共享有序映射：红黑全局锁太粗；无锁 BST 要帮旋转与 ABA。跳表层间独立：插入先串底层再从低到高挂快进指针；删除标记再解链。缺口是<strong>线性化点落在某层指针从旧后继改到新后继</strong>，查找要能容忍「看见正在插入的半成品」。</p><p><span class="marginnote">Java <code>ConcurrentSkipListMap</code> 是实践标杆之一。Pugh 1990 技术报告写了并发维护。Herlihy–Shavit 教材有整章跳表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找：从高层向右向下，读指针；若实现用标记位表示「节点已删」，查找跳过标记节点。插入：找到每层前驱，CAS 前驱的 next；失败则重找。删除：先逻辑删（标记），再物理摘指针，避免查找走到野指针。</p>',8)),(e(),l(d,null,{default:r(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRCH%5B%22%E6%9F%A5%E6%89%BE%3A%20%E5%90%91%E5%8F%B3%E5%86%8D%E5%90%91%E4%B8%8B%22%5D%20--%3E%20READ%5B%22%E5%8F%AA%E8%AF%BB%E6%8C%87%E9%92%88%22%5D%0A%20%20INS%5B%22%E6%8F%92%E5%85%A5%22%5D%20--%3E%20CAS%5B%22CAS%20%E5%89%8D%E9%A9%B1%E7%9A%84%20next%22%5D%0A%20%20DEL%5B%22%E5%88%A0%E9%99%A4%22%5D%20--%3E%20MARK%5B%22%E6%A0%87%E8%AE%B0%E5%86%8D%E8%A7%A3%E9%93%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/treap">Treap</a>：期望对数同类，并发时跳表少旋转。进度：无锁查找常见；插入可能锁或 CAS 重试，活锁要限次。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>层高仍插入时随机，与并发独立。ABA：节点复用时 next 或标记可能骗过 CAS，回收用 hazard / epoch，后课再钉，本课承认「节点不能立即重用」。内存序：发布节点内容先于把指针 CAS 进表，见<a href="/cs/atomic-rmw">原子 RMW</a>。</p><p>不要在本课写可运行的竞态 exploit；只写结构。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把完整无锁证明写完，不引入 skip list 的确定性变体。堆的可并合同与跳表无关：下一课左偏树与配对堆，为优先队列减键与合并做准备。</p><p>后课默认：并发有序映射可用跳表。可合并堆从左偏与配对开始。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>并发跳表：查找只读，更新 CAS 或分层锁。</li><li>删除常分标记与摘链；注意 ABA 与回收。</li><li>下一课转向可并堆，不是再一层跳表。</li><li>出处：Pugh, 1990；Herlihy and Shavit。</li></ul>',9))])}const C=o(h,[["render",A]]);export{B as __pageData,C as default};
